<?php if ($photos): ?><script>document.addEventListener('DOMContentLoaded',()=>{const photos=<?= json_encode($photos, JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,box=document.getElementById('facilityLightbox'),img=document.getElementById('facilityLightboxImage'),title=document.getElementById('facilityLightboxTitle'),desc=document.getElementById('facilityLightboxDescription');let current=0,previous=null;const show=i=>{current=(i+photos.length)%photos.length;const p=photos[current];img.src=p.image;img.alt=p.title+' at KVK Kokrajhar';title.textContent=p.title;desc.textContent=p.description};const open=i=>{previous=document.activeElement;show(i);box.classList.add('open');box.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';document.getElementById('facilityClose').focus()};const close=()=>{box.classList.remove('open');box.setAttribute('aria-hidden','true');document.body.style.overflow='';previous?.focus()};document.querySelectorAll('.fg-card').forEach(card=>card.addEventListener('click',()=>open(Number(card.dataset.index))));document.getElementById('facilityPrev').addEventListener('click',()=>show(current-1));document.getElementById('facilityNext').addEventListener('click',()=>show(current+1));document.getElementById('facilityClose').addEventListener('click',close);box.addEventListener('click',e=>{if(e.target===box)close()});document.addEventListener('keydown',e=>{if(!box.classList.contains('open'))return;if(e.key==='Escape')close();if(e.key==='ArrowLeft')show(current-1);if(e.key==='ArrowRight')show(current+1)})});</script><?php endif; ?>
